def body_language_version(universe,context,row):
    """Build the `body-language-version` record for one semantic universe.

    The inherited policy requires the frame's languageVersion component to be "canonical identity
    bytes supplied by ResolvedInputs/PlanId, not a human display string". The compiler identity that
    satisfies it is not missing and never was: the universe's own `nativeContextId` - a reference
    Run closure already requires to be Plan-selected - reaches the admitted retained context, whose
    `toolchain` carries `rustcVersion`/`rustCommitHash` for Rust and
    `compilerName`/`compilerVersion`/`compilerPackageDigest` for TypeScript. Following an existing
    admitted reference needs no new universe field.

    What goes in is the identity of the component that INTERPRETS the body span, plus the selected
    source dialect. What stays out is operational platform, paths, resolution inputs, build tooling
    and option synthesis; the registry row lists each exclusion with its reason.

    Rust's `edition` is a map from crate NAME to year. Its distinct VALUE set decides: exactly one
    member is the dialect of every body in that universe. More than one means the owning crate
    decides and nothing this Run committed joins an anchor PATH to a crate NAME, so this REFUSES
    rather than guessing a module layout.

    Pure: it reads two already-retained records and the registry row, and touches no Run state."""
    binding=row.get('languageVersionBinding')
    if binding is None:raise C.AdmissionError('BODY_LANGUAGE_UNIVERSE_UNBOUND:'+row['language'])
    record={'schemaVersion':1,'languageId':binding['languageId']}
    for name,source in binding['fields'].items():
        if 'const' in source:record[name]=source['const'];continue
        node=context if source['source']=='native-context' else universe
        for step in source['path']:node=node[step]
        record[name]=node
    dialect=binding['dialect']
    if dialect is None:record['dialect']=None
    else:
        node=universe if dialect['source']=='universe' else context
        for step in dialect['path']:node=node[step]
        if dialect['form']!='unique-value-of-map':raise C.AdmissionError('BODY_LANGUAGE_DIALECT_FORM')
        distinct={C.canonical(value) for value in node.values()}
        if not distinct:raise C.AdmissionError(dialect['onEmpty']+':'+binding['languageId'])
        if len(distinct)>1:raise C.AdmissionError(dialect['onAmbiguous']+':'+binding['languageId']+':'+str(len(distinct)))
        record['dialect']={dialect['key']:next(iter(node.values()))}
    schema=copy.deepcopy(SCHEMA);schema['$ref']=binding['record']
    C.validate(schema,record)
    return record

